// Helper functions for the dynamic system
class ProjectsDataManager {
    constructor() {
        this.projects = Object.values(projectsData);
    }

    // Get all projects
    getProjects() {
        return this.projects.sort((a, b) => parseInt(b.date) - parseInt(a.date));
    }

    // Get single project by ID
    getProject(id) {
        return projectsData[id] || null;
    }

    // Get projects count
    getProjectsCount() {
        return this.projects.length;
    }

    // Check if project exists
    hasProject(id) {
        return projectsData.hasOwnProperty(id);
    }
}

// Create global instance
window.projectsDataManager = new ProjectsDataManager();

// For backward compatibility, also create the projectLoader interface
window.projectLoader = {
    async getProjects() {
        return window.projectsDataManager.getProjects();
    },
    async getProject(id) {
        return window.projectsDataManager.getProject(id);
    },
    async loadAllProjects() {
        return window.projectsDataManager.getProjects();
    }
};